import React from 'react';
import { Link } from 'react-router-dom';

export default function Navbar() {
return (
<nav style={{ background: '#333', padding: '10px' }}>
<ul style={{ display: 'flex', gap: '20px', listStyle: 'none', color: 'white' }}>
<li><Link to="/" style={{ color: 'white', textDecoration: 'none' }}>Home</Link></li>
<li><Link to="/about" style={{ color: 'white', textDecoration: 'none' }}>About</Link></li>
<li><Link to="/projects" style={{ color: 'white', textDecoration: 'none' }}>Projects</Link></li>
<li><Link to="/contact" style={{ color: 'white', textDecoration: 'none' }}>Contact</Link></li>
<li style={{ marginLeft: 'auto' }}><Link to="/login" style={{ color: 'white', textDecoration: 'none' }}>Login</Link></li>
</ul>
</nav>
);
}
